const unwrap = x => x?.body && typeof x.body === 'object' ? x.body : x;
const funnel = unwrap($('Get funnel').first().json);
const metrics = unwrap($('Get metrics').first().json);
if (funnel?.error || metrics?.error || !Array.isArray(funnel?.stages) || !funnel.stages.length ||
    !Number.isFinite(metrics?.total_leads) || funnel.stages.some(s => typeof s.stage !== 'string' || !Number.isInteger(s.count) || s.count < 0)) {
  return [{json: {ok: false, data: null, summary: 'Pipeline data is unavailable; backend funnel or metrics could not be verified.'}}];
}
const stages = funnel.stages.map(s => ({stage: s.stage, count: s.count}));
const keys = ['total_leads', 'new_7d', 'stalled_count', 'high_intent_count', 'needs_review_count',
  'viewings_upcoming', 'completion_rate', 'viewing_rate', 'avg_hours_to_completion', 'avg_hours_to_viewing'];
const kpis = {};
for (const k of keys) if (Number.isFinite(metrics[k])) kpis[k] = metrics[k];
const summary = 'Stage counts: ' + stages.map(s => `${s.stage}=${s.count}`).join(', ') +
  '. Aggregate KPIs: ' + Object.entries(kpis).map(([k,v]) => `${k}=${v}`).join(', ') + '.';
return [{json: {ok: true, data: {stages, conversion: funnel.conversion ?? {}, metrics: kpis}, summary}}];
